/**
 * Netlify Function — /api/confirm  (the admin one-click "Confirm & deliver")
 *
 * Reached from the action email sent by submission-created. The link is signed
 * with an HMAC of (type|email|key|ts) using ADMIN_KEY, so only links generated by
 * our own emails work — the raw admin key is never put in the URL.
 *
 *   product : mints a 7-day Supabase signed link for the file + emails the buyer
 *   sub     : marks the invoice paid + activates the subscription + emails buyer
 *
 * Env: ADMIN_KEY, SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */
import crypto from "node:crypto";

const SUPABASE_URL = (process.env.SUPABASE_URL || "https://ddyszmfffyedolkcugld.supabase.co").replace(/\/$/, "");
const SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;
const ADMIN_KEY = process.env.ADMIN_KEY || "";

const esc = (v) => String(v == null ? "" : v)
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const looksLikeEmail = (v) => typeof v === "string" && /^[^\s@<>"']+@[^\s@<>"']+\.[^\s@<>"']+$/.test(v);
const MAX_AGE_MS = 30 * 24 * 3600 * 1000;
// Links sent before timestamps were added carry no ts. They keep working
// until this date so orders already waiting in the inbox can be delivered.
const LEGACY_UNTIL = Date.parse("2026-11-15T00:00:00Z");
const hmac = (parts) => crypto.createHmac("sha256", ADMIN_KEY).update(parts.join("|")).digest("hex").slice(0, 32);
const same = (a, b) => a.length === b.length && crypto.timingSafeEqual(Buffer.from(a), Buffer.from(b));

// Every value interpolated below is escaped by the callers; page() itself
// takes trusted markup.
const page = (title, body) => new Response(
  `<!doctype html><meta charset=utf-8><meta name=viewport content="width=device-width,initial-scale=1">
   <title>${title}</title><body style="font-family:Inter,system-ui,Arial;background:#0F172A;color:#F1F5F9;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0">
   <div style="max-width:460px;padding:2rem;text-align:center"><h1 style="color:#0EA5E9;font-size:1.4rem">${title}</h1><p style="color:#CBD5E1;line-height:1.6">${body}</p>
   </div>`,
  { headers: {
    "Content-Type": "text/html; charset=utf-8",
    "Cache-Control": "no-store",
    // The page is static text: no script, no frame, nothing loaded.
    "Content-Security-Policy": "default-src 'none'; style-src 'unsafe-inline'; frame-ancestors 'none'; base-uri 'none'; form-action 'none'",
    "Referrer-Policy": "no-referrer",
  } });

const sb = (path, opts = {}) => fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
  ...opts, headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": "application/json", ...(opts.headers || {}) },
});
// status-alert answers {sent:true} when the provider accepted the message,
// {skipped:true} when no key is configured and 502 when the provider refused
// it. A mail is treated as sent only on {sent:true}, and tried twice, because
// a "Delivered" page for an email that never left is the failure this guards.
async function mail(to, subject, html) {
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const r = await fetch(`${SUPABASE_URL}/functions/v1/status-alert`, { method: "POST", headers: { Authorization: `Bearer ${SERVICE_KEY}`, "Content-Type": "application/json" }, body: JSON.stringify({ to, subject, html }) });
      const j = await r.json().catch(() => ({}));
      if (r.ok && j && j.sent === true) return true;
      console.log("[confirm] mail not sent, attempt", attempt, "status", r.status, JSON.stringify(j).slice(0, 200));
    } catch (e) { console.log("[confirm] mail failed, attempt", attempt, e.message); }
    if (attempt === 1) await new Promise((res) => setTimeout(res, 1500));
  }
  return false;
}
const notSent = (email) => page("Email not sent", `The email to <b>${esc(email)}</b> could not be sent, so nothing was delivered. This link has not been used up: open it again in a minute, or deliver by hand.`);

export default async (req) => {
  if (!ADMIN_KEY || !SERVICE_KEY) return page("Not configured", "ADMIN_KEY / service key missing.");
  const q = new URL(req.url).searchParams;
  const type = q.get("type") || "", email = q.get("email") || "", key = q.get("key") || "", sig = q.get("sig") || "", ts = q.get("ts") || "";
  const valid = ts
    ? same(sig, hmac([type, email, key, ts])) && Date.now() - Number(ts) <= MAX_AGE_MS
    : same(sig, hmac([type, email, key])) && Date.now() < LEGACY_UNTIL;
  if (!valid) return page("Invalid link", "This confirmation link is not valid or has expired.");
  if (!looksLikeEmail(email)) return page("Invalid email", "The buyer's email address is not valid, so nothing was sent. Deliver this order by hand.");

  // Each link works once, so a forwarded or reused email cannot deliver twice.
  let used = null;
  try { const { getStore } = await import("@netlify/blobs"); used = getStore("confirm-links"); }
  catch (e) { console.log("[confirm] blobs unavailable", e.message); }
  if (used && (await used.get(sig).catch(() => null))) {
    return page("Already done", "This link has already been used. Nothing was sent again.");
  }
  const markUsed = async () => { if (used) await used.set(sig, String(Date.now())).catch(() => {}); };

  try {
    if (type === "product") {
      // A bundle's key is its files joined by commas. Every file is signed
      // before anything is sent, so a buyer gets the whole bundle or the
      // owner is told nothing went out.
      const files = key.split(",").map((f) => f.trim()).filter(Boolean);
      const links = [];
      for (const file of files) {
        const r = await fetch(`${SUPABASE_URL}/storage/v1/object/sign/products/${encodeURIComponent(file)}`, {
          method: "POST", headers: { Authorization: `Bearer ${SERVICE_KEY}`, apikey: SERVICE_KEY, "Content-Type": "application/json" },
          body: JSON.stringify({ expiresIn: 7 * 24 * 3600 }),
        });
        if (!r.ok) {
          console.log("[confirm] sign failed:", file, r.status, (await r.text()).slice(0, 400));
          return page("Could not sign file", `The download link for ${esc(file)} could not be created, so nothing was sent. Check that the file is in the products store, then use this link again.`);
        }
        links.push({ file, url: `${SUPABASE_URL}/storage/v1${(await r.json()).signedURL}` });
      }
      if (!links.length) return page("Nothing to send", "This link names no file. Deliver this order by hand.");
      const btn = (u, label) => `<p><a href="${u}" style="background:#0369A1;color:#fff;text-decoration:none;padding:12px 22px;border-radius:8px;font-weight:700;font-family:Inter,Arial">${label}</a></p>`;
      const body = links.length === 1
        ? btn(links[0].url, "Download your file →")
        : `<p>Your bundle has ${links.length} files. Each link below downloads one of them.</p>` +
          links.map((l) => btn(l.url, esc(l.file.replace(/^.*\//, "").replace(/^ImpactMojo-/, "").replace(/\.[a-z]+$/i, "").replace(/-/g, " ")))).join("");
      if (!(await mail(email, "Your ImpactMojo download", `<p>Thank you for your purchase!</p>${body}<p>${links.length === 1 ? "This link works" : "These links work"} for 7 days. Reply to this email if you have any trouble.</p>`))) return notSent(email);
      await markUsed();
      return page("Delivered ✓", `${links.length === 1 ? "The file was" : links.length + " files were"} emailed to <b>${esc(email)}</b>.`);
    }
    if (type === "sub") {
      const pr = await sb(`subscription_payments?reference=eq.${encodeURIComponent(key)}`, { method: "PATCH", headers: { Prefer: "return=representation" }, body: JSON.stringify({ status: "paid" }) });
      const rows = await pr.json();
      if (!rows.length) return page("Reference not found", `No invoice with reference ${esc(key)}.`);
      const today = new Date().toISOString().slice(0, 10);
      await sb(`subscriptions?id=eq.${rows[0].subscription_id}`, { method: "PATCH", body: JSON.stringify({ status: "active", last_paid: today }) });
      if (!(await mail(email, "Your ImpactMojo subscription is active", `<p>Payment received — your subscription is active. Thank you!</p><p>We'll email your next UPI QR when it's time to renew.</p>`))) return notSent(email);
      await markUsed();
      return page("Activated ✓", `Subscription for <b>${esc(email)}</b> marked paid and active.`);
    }
    return page("Unknown action", "Nothing to do.");
  } catch (e) {
    console.log("[confirm] failed:", e && e.message);
    return page("Error", "Something went wrong and the order may not have been completed. Check the function log before trying again.");
  }
};

export const config = { path: "/api/confirm" };
